"""Tests for the Power BI project in dashboard/ (generated by src/build_dashboard.py).

* PBIR report JSON validated against Microsoft's schemas (vendored in tests/pbir_schemas/).
* Every field the report uses exists in the model; sector indices are excluded on every page.
* Model structure: relationships, sort orders, formats, auto date/time off, measures.dax.
* If Power BI Desktop is installed: the TMDL is parsed by Desktop's own serializer, and all
  measures are evaluated on Desktop's engine (msmdsrv) and compared with the CSVs.
"""
from __future__ import annotations

import json
import re
import subprocess
import sys
from pathlib import Path

import pandas as pd
import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

import build_dashboard as bd  # noqa: E402

DASH = ROOT / "dashboard"
REPORT = DASH / "tse_inflation.Report"
MODEL = DASH / "tse_inflation.SemanticModel" / "definition"
PBI = ROOT / "data" / "processed" / "powerbi"
SCHEMAS = Path(__file__).parent / "pbir_schemas"
PREFIX = "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/"
DESKTOP = Path(r"C:\Program Files\Microsoft Power BI Desktop\bin\msmdsrv.exe")
needs_desktop = pytest.mark.skipif(not DESKTOP.exists(), reason="Power BI Desktop not installed")


# ------------------------------- PBIR schema ------------------------------ #
def _validator(uri):
    from jsonschema import Draft7Validator
    from referencing import Registry, Resource

    def retrieve(u):
        return Resource.from_contents(json.loads((SCHEMAS / u[len(PREFIX):]).read_text(encoding="utf-8")))
    return Draft7Validator({"$ref": uri}, registry=Registry(retrieve=retrieve))


def schema_errors(doc: dict) -> list[str]:
    return [f"{'/'.join(map(str, e.path))}: {e.message[:150]}"
            for e in _validator(doc["$schema"]).iter_errors(doc)]


REPORT_JSON = sorted(p for p in REPORT.rglob("*.json")
                     if json.loads(p.read_text(encoding="utf-8")).get("$schema", "").startswith(PREFIX))


PAGE_NAMES = ["نمای کلی: بورس در برابر تورم", "پراکندگی: ۸ سهم نمونه، نه کل بازار",
              "تعطیلی بازار و دارایی امن", "زمان ورود"]
RLM = "\u200f"


def plain(text: str) -> str:
    return text.replace(RLM, "")


def test_report_has_four_pages_in_order():
    pages = json.loads((REPORT / "definition" / "pages" / "pages.json").read_text(encoding="utf-8"))
    names = [json.loads((REPORT / "definition" / "pages" / p / "page.json").read_text(encoding="utf-8"))["displayName"]
             for p in pages["pageOrder"]]
    assert [plain(n) for n in names] == PAGE_NAMES
    assert len(REPORT_JSON) > 40


@pytest.mark.parametrize("path", REPORT_JSON, ids=lambda p: p.relative_to(REPORT).as_posix()[-60:])
def test_report_json_matches_schema(path):
    errs = schema_errors(json.loads(path.read_text(encoding="utf-8")))
    assert not errs, errs[:5]


def test_schema_validation_catches_errors():
    good = json.loads(next(p for p in REPORT_JSON if p.name == "visual.json").read_text(encoding="utf-8"))
    bad = dict(good, position={"x": "left"})
    assert schema_errors(bad)


# --------------------------- report <-> model ----------------------------- #
def test_every_report_field_exists_in_model():
    assert bd.check_report_fields() == []


def _pages():
    out = []
    for pj in (REPORT / "definition" / "pages").glob("*/page.json"):
        page = json.loads(pj.read_text(encoding="utf-8"))
        visuals = [json.loads(v.read_text(encoding="utf-8")) for v in pj.parent.glob("visuals/*/visual.json")]
        out.append((page, visuals))
    return out


def _filter_values(f):
    """Values of a categorical 'In' filter; [] for the empty filter cards Desktop adds for each
    field of a visual (no condition, nothing filtered)."""
    cond = (f.get("filter", {}).get("Where") or [{}])[0].get("Condition", {})
    if "In" not in cond:
        return []
    return [v[0]["Literal"]["Value"].strip("'") for v in cond["In"]["Values"]]


def test_sector_indices_never_shown():
    for page, visuals in _pages():
        pf = [f for f in page["filterConfig"]["filters"]
              if f["field"]["Column"]["Property"] == "type"]
        assert len(pf) == 1 and pf[0].get("isLockedInViewMode") is True, page["displayName"]
        allowed = set(_filter_values(pf[0]))
        assert "sector_index" not in allowed, page["displayName"]
        if "stock" in allowed:
            assert allowed <= {"stock", "market_index", "portfolio"}, page["displayName"]
        for v in visuals:
            for f in v.get("filterConfig", {}).get("filters", []):
                assert "sector_index" not in _filter_values(f)


