def test_measures_in_measures_table_and_dax_file():
    required = ["CPI growth (×)", "Index real cum 3y", "Equal-weight real cum 3y",
                "Stocks beating inflation", "Closure real loss (pro-rated)", "Selected real CAGR",
                "Selected real vol", "Selected max drawdown", "Selected months beating inflation"]
    names = [m["name"] for m in bd.MEASURES]
    assert set(required) <= set(names)
    mt = tmdl("tables/_Measures.tmdl")
    dax = (DASH / "measures.dax").read_text(encoding="utf-8")
    for n in names:
        assert f"measure {bd.q(n)} =" in mt
        assert f"{bd.q(n)} =" in dax
    for t in (MODEL / "tables").glob("*.tmdl"):
        if t.stem != "_Measures":
            assert "\tmeasure " not in t.read_text(encoding="utf-8"), t.name
    pct_measures = [m for m in bd.MEASURES if m["format"] == bd.PCT]
    assert len(pct_measures) >= 20


def test_m_added_columns_match_python_equivalents():
    """The engine test model reproduces the Power Query added columns in Python."""
    for table, cols in bd.ADDED.items():
        df = bd.table_frame(table)
        for name, expr, _ in cols:
            for label in re.findall(r'then "([^"]+)"', expr) + re.findall(r'else "([^"]+)"', expr):
                assert label.replace("#(200F)", RLM) in set(df[name].astype(str)), (table, name, label)


