@needs_desktop
def test_tmdl_parses_with_power_bi_serializer():
    r = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File",
                        str(DASH / "tools" / "check_tmdl.ps1"), str(MODEL)],
                       capture_output=True, text=True, encoding="utf-8", timeout=300)
    assert r.returncode == 0, r.stdout + r.stderr
    assert "table _Measures: 0 columns, %d measures" % len(bd.MEASURES) in r.stdout
    assert r.stdout.count("relationship ") == 5


def parse_results(path: Path) -> dict[int, pd.DataFrame]:
    out, cur, rows = {}, None, []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("## "):
            if cur is not None:
                out[cur] = rows
            cur, rows = int(line[3:]), []
        elif line:
            rows.append(line.split("\t"))
    out[cur] = rows
    frames = {}
    for k, r in out.items():
        assert not r[0][0].startswith("ERROR"), f"query {k}: {r[0][0]}"
        cols = [re.sub(r"^.*\[(.*)\]$", r"\1", c) for c in r[0]]
        frames[k] = pd.DataFrame(r[1:], columns=cols)
    return frames


def num(x):
    return float(x) if x not in ("", None) else float("nan")


@pytest.fixture(scope="module")
def engine(tmp_path_factory):
    if not DESKTOP.exists():
        pytest.skip("Power BI Desktop not installed")
    out = tmp_path_factory.mktemp("engine") / "results.tsv"
    r = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File",
                        str(DASH / "tools" / "test_model_on_engine.ps1"), "-OutFile", str(out),
                        "-Python", sys.executable],
                       capture_output=True, text=True, encoding="utf-8", timeout=600, cwd=ROOT)
    assert r.returncode == 0 and "refresh: OK" in r.stdout, r.stdout + r.stderr
    return parse_results(out)


def test_engine_headline_measures(engine):
    rs = pd.read_csv(PBI / "risk_summary.csv").set_index("code")
    cl = pd.read_csv(PBI / "closure_summary.csv").set_index(["series_code", "window"])
    for q in (1, 2):
        r = engine[q].iloc[0]
        assert num(r["cpi_growth_x"]) == pytest.approx(1 + rs.loc["cpi", "nominal_cum_3y"])
        assert num(r["index_real_cum_3y"]) == pytest.approx(rs.loc["index_total", "real_cum_3y"])
        assert r["stocks_beating"] == "3 / 8"
        assert num(r["closure_loss_prorated"]) == pytest.approx(cl.loc[("index_total", "on_reopening"), "real_prorated"])
    r = engine[1].iloc[0]
    assert num(r["ew_real_cum_3y"]) == pytest.approx(rs.loc["index_equal_weight", "real_cum_3y"])
    assert num(r["closure_loss_whole_months"]) == pytest.approx(cl.loc[("index_total", "on_reopening"), "real_whole_months"])


