def test_engine_series_tables(engine):
    rs = pd.read_csv(PBI / "risk_summary.csv").set_index("code")
    t = engine[5].set_index("series_code")
    assert set(t.index) == set(rs.index)
    for code in rs.index:
        assert num(t.loc[code, "real_cagr"]) == pytest.approx(rs.loc[code, "real_cagr"])
