def test_theme_blue_green_red_segoe():
    th = json.loads((DASH / "theme.json").read_text(encoding="utf-8"))
    reg = json.loads((REPORT / "StaticResources" / "RegisteredResources" / bd.CUSTOM_THEME).read_text(encoding="utf-8"))
    assert th == reg
    assert th["good"] == "#2E7D32" and th["bad"] == "#C62828"
    assert {t["fontFace"] for t in th["textClasses"].values()} == {"Segoe UI"}
    report = json.loads((REPORT / "definition" / "report.json").read_text(encoding="utf-8"))
    assert report["themeCollection"]["customTheme"]["name"] == bd.CUSTOM_THEME


def test_engine_colour_and_correlation_measures(engine):
    rs = pd.read_csv(PBI / "risk_summary.csv").set_index("code")
    for _, r in engine[13].iterrows():
        v = rs.loc[r["series_code"], "real_cagr"]
        assert r["color"] == ("#2E7D32" if v > 0 else "#C62828" if v < 0 else "#8C8C8C"), r["series_code"]
    corr = pd.read_csv(PBI / "correlation_long.csv").set_index(["series_a_code", "series_b_code"])
    assert len(engine[14]) == 100
    for _, r in engine[14].iterrows():
        assert num(r["corr"]) == pytest.approx(corr.loc[(r["series_a_code"], r["series_b_code"]), "corr_real_return_per_month"])
